 // 배틀 중 열리는 창: 지령 선언·교대 선택·결과·분석·포켓몬 편집
 static class DirectiveRules {
  static readonly string[] Forms={"물러나","피해라","돌아와","버텨라","맞춰라"};
  public static bool IsForm(string name){return Forms.Any(x=>(name??"").Contains(x));}
  public static string Label(TurnSelection v){string action=v.SwitchIndex>=0?"교대":"기술";return action+" · 4식 "+(v.Form.Length>0?v.Form:"—")+" · 지령 "+(v.Order.Length>0?v.Order:"—")+" · 선행 "+(v.PreInputs==null||v.PreInputs.Count==0?"—":v.PreInputs.Count+"개");}
 }
 class DirectiveForm:Form {
  public TurnSelection Value;PixelComboBox action,target,form,order;PixelCheckedListBox preInputs;List<Fighter> reserves;TrainerBattleState state;TrainerRecord trainer;Fighter fighter;bool loading;
  public DirectiveForm(TrainerRecord source,TrainerBattleState used,List<Fighter> team,Fighter active,TurnSelection input){Load+=(s,e)=>Theme.Enlarge(this);trainer=source;state=used;reserves=team;fighter=active;Value=input.Copy();Text="행동 / 4식 / 지령 / 선행입력";Size=new Size(630,500);StartPosition=FormStartPosition.CenterParent;BackColor=Color.White;Font=Theme.UI();var table=Theme.Table();action=Theme.Combo(new[]{"기술 사용","교대"},Value.SwitchIndex>=0?"교대":"기술 사용");target=Theme.Combo(new[]{"선택하세요"}.Concat(reserves.Select(x=>x.Data.name)),Value.SwitchIndex>=0&&Value.SwitchIndex<reserves.Count?reserves[Value.SwitchIndex].Data.name:"선택하세요");form=Theme.Combo(new[]{"사용 안 함"},"사용 안 함");order=Theme.Combo(new[]{"사용 안 함"},"사용 안 함");preInputs=new PixelCheckedListBox{Dock=DockStyle.Fill,CheckOnClick=true,Font=Theme.Input(),BorderStyle=BorderStyle.FixedSingle};Theme.Row(table,"이번 행동",action);Theme.Row(table,"교대 대상",target);Theme.Row(table,"4식 (턴당 1회)",form);Theme.Row(table,"지령 (턴당 1개)",order);Theme.Row(table,"선행입력",preInputs);table.RowStyles[4].Height=100;var note=Theme.Label(trainer==null?"트레이너 없이도 포켓몬이 보유한 선행입력 포텐셜은 선택할 수 있습니다.":"모두 선택 사항입니다. 『돌아와!』는 교대와 함께 선언합니다.",48);note.ForeColor=Theme.Muted;Theme.Row(table,"규칙",note);var foot=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=62,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(12)};var apply=new FlatButton{Text="선택",Primary=true,Size=new Size(95,36)};var cancel=new FlatButton{Text="취소",Size=new Size(85,36),DialogResult=DialogResult.Cancel};foot.Controls.AddRange(new Control[]{apply,cancel});Controls.Add(table);Controls.Add(foot);action.SelectedIndexChanged+=(s,e)=>FillChoices();apply.Click+=(s,e)=>Apply();FillChoices();}
  IEnumerable<string> EnabledNames(){return (trainer==null||trainer.potentials==null?Enumerable.Empty<PotentialRecord>():trainer.potentials.Where(x=>x.enabled&&x.slot=="지령"&&x.name.Length>0)).Select(x=>x.name);}
  void FillChoices(){if(loading)return;loading=true;bool switching=(string)action.SelectedItem=="교대";string oldForm=Value.Form,oldOrder=Value.Order;var forms=EnabledNames().Where(DirectiveRules.IsForm).Where(x=>TrainerAccessRules.CanUseForm(x,trainer,state,fighter.Data.potentials)).Where(x=>!state.UsedForms.Contains(x)).Where(x=>switching?x.Contains("돌아와"):!x.Contains("돌아와")).Distinct().ToArray();form.Items.Clear();form.Items.Add("사용 안 함");form.Items.AddRange(forms.Cast<object>().ToArray());form.SelectedItem=forms.Contains(oldForm)?oldForm:"사용 안 함";var orders=EnabledNames().Where(x=>!DirectiveRules.IsForm(x)).Where(x=>TrainerAccessRules.CanUseOrder(x,trainer,state,fighter.Data.potentials)).Where(x=>!state.UsedOrders.Contains(x)).Distinct().ToArray();order.Items.Clear();order.Items.Add("사용 안 함");if(!switching)order.Items.AddRange(orders.Cast<object>().ToArray());order.SelectedItem=!switching&&orders.Contains(oldOrder)?oldOrder:"사용 안 함";preInputs.Items.Clear();foreach(var p in (fighter.Data.potentials??new Potential[0]).Where(x=>x!=null&&x.activation=="선행"&&(!(x.uses??"").Contains("1/")||state.Usage.CanUse(PotentialKeys.For(fighter.Data,x),x.uses))))preInputs.AddItem(p.name,(Value.PreInputs??new List<string>()).Contains(p.name));target.Enabled=switching;form.Enabled=forms.Length>0;order.Enabled=!switching&&orders.Length>0;preInputs.Enabled=preInputs.Items.Count>0;loading=false;}
  void Apply(){bool switching=(string)action.SelectedItem=="교대";int selected=target.SelectedIndex-1;if(switching&&selected<0){GameDialog.Show(this,"교대할 포켓몬을 선택하세요.");return;}var chosen=preInputs.CheckedItems.Cast<object>().Select(x=>x.ToString()).ToList();foreach(string name in chosen.ToArray()){var p=(fighter.Data.potentials??new Potential[0]).FirstOrDefault(x=>x!=null&&x.name==name);if(p!=null&&(p.description??"").Contains("할 수 있다")&&GameDialog.Show(this,"『"+name+"』을 발동할까요?","선택 발동",MessageBoxButtons.YesNo)!=DialogResult.Yes)chosen.Remove(name);}string selectedForm=(string)form.SelectedItem,selectedOrder=(string)order.SelectedItem;Value=new TurnSelection{SwitchIndex=switching?selected:-1,Form=selectedForm=="사용 안 함"?"":selectedForm,Order=selectedOrder=="사용 안 함"?"":selectedOrder,PreInputs=chosen};DialogResult=DialogResult.OK;Close();}
 }
 class SwitchPromptForm:Form {
  public Fighter Selected;PixelComboBox target;SwitchRequest request;
  public SwitchPromptForm(SwitchRequest value){Load+=(s,e)=>Theme.Enlarge(this);request=value;Text="교대 대상 선택";Size=new Size(520,270);MinimumSize=new Size(430,230);StartPosition=FormStartPosition.CenterParent;BackColor=Color.White;Font=Theme.UI();var table=Theme.Table();target=Theme.Combo((value.Candidates??new Fighter[0]).Select(x=>x.Data.name),"");var title=Theme.Label((value.Timing==SwitchTiming.TurnEnd?"턴 마지막":"턴 중간")+" 교대 요청 · "+value.Source,48);title.ForeColor=Theme.Muted;Theme.Row(table,"교대 대상",target);var note=Theme.Label("효과가 성립했습니다. 다음 행동 전에 장소에 낼 포켓몬을 선택하세요.",58);note.ForeColor=Theme.Muted;Theme.Row(table,"안내",note);var foot=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=62,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(12)};var apply=new FlatButton{Text="교대",Primary=true,Size=new Size(90,36)};var cancel=new FlatButton{Text="취소",Size=new Size(85,36),DialogResult=DialogResult.Cancel};foot.Controls.AddRange(new Control[]{apply,cancel});Controls.Add(table);Controls.Add(foot);apply.Click+=(s,e)=>Apply();if(target.Items.Count>0)target.SelectedIndex=0;}
  void Apply(){if(target.SelectedIndex<0){GameDialog.Show(this,"교대할 포켓몬을 선택하세요.");return;}Selected=request.Candidates[target.SelectedIndex];DialogResult=DialogResult.OK;Close();}
 }
 class ResultForm:Form {
  LogView text;
  public ResultForm(){Text="계산 내역 · AA BATTLE";Size=new Size(600,480);MinimumSize=new Size(450,300);StartPosition=FormStartPosition.CenterParent;BackColor=Color.White;Font=Theme.UI();var notice=Theme.Label("대미지 / 무효 사유 / 상태 처리 / 턴 종료 효과",45);notice.Padding=new Padding(15,0,10,0);notice.ForeColor=Theme.Muted;text=new LogView{Dock=DockStyle.Fill};var padding=new Panel{Dock=DockStyle.Fill,Padding=new Padding(20,12,20,20)};padding.Controls.Add(text);Controls.Add(padding);Controls.Add(notice);}
