 }
 class AnalysisForm:Form {
  public AnalysisForm(Fighter target){Load+=(s,e)=>Theme.Enlarge(this);Text=target.Data.name+" · 데이터 해석";Size=new Size(980,680);StartPosition=FormStartPosition.CenterParent;BackColor=Color.White;Font=Theme.UI();var split=new SplitContainer{Dock=DockStyle.Fill,SplitterDistance=500};var art=new AAView{Dock=DockStyle.Fill,Art=target.AA};var info=new LogView{Dock=DockStyle.Fill};var visible=(target.Data.potentials??new Potential[0]).Where(p=>p!=null&&p.id!="전용").Select(p=>"『"+p.name+"』 "+p.description).ToArray();info.SetLog("【"+target.Data.name+"】\n레벨: "+target.Data.level+"\n타입: "+string.Join(" / ",target.Data.types)+"\n특성: "+(target.Data.ability.Length>0?target.Data.ability:"없음")+"\n종족치: "+string.Join(" / ",target.Data.@base)+"\n기술: "+string.Join(" / ",target.Moves)+"\n\n【공개 포텐셜】\n"+(visible.Length>0?string.Join("\n",visible):"없음")+"\n\n전용 포텐셜·도구·현재 체력은 공개하지 않습니다.");split.Panel1.Padding=new Padding(16);split.Panel2.Padding=new Padding(16);split.Panel1.Controls.Add(art);split.Panel2.Controls.Add(info);Controls.Add(split);}
 }
 class FighterForm:Form {
  public Fighter Value;Database db;int other;Rules rules;PixelComboBox source,status;PixelTextBox name,aa,ability,item;PixelNumber level,hp;PixelComboBox[] type=new PixelComboBox[3],moves=new PixelComboBox[4];PixelNumber[] bases=new PixelNumber[6],ivs=new PixelNumber[6],stages=new PixelNumber[6],mult=new PixelNumber[6];
  public FighterForm(Database database,Fighter input,int opponent,Rules r){Load+=(s,e)=>Theme.Enlarge(this);db=database;other=opponent;rules=r;Value=input.Copy();Text="포켓몬 / AA 편집";Size=new Size(790,700);MinimumSize=new Size(650,590);StartPosition=FormStartPosition.CenterParent;Font=Theme.UI();BackColor=Color.White;
   var tabs=new TabControl{Dock=DockStyle.Fill,ItemSize=new Size(110,30)};Theme.Tabs(tabs);var dataPage=new TabPage("포켓몬"){AutoScroll=true,BackColor=Color.White};var aaPage=new TabPage("아스키아트"){BackColor=Color.White};var statsPage=new TabPage("능력치"){BackColor=Color.White};var movesPage=new TabPage("기술"){BackColor=Color.White};tabs.TabPages.AddRange(new[]{dataPage,aaPage,statsPage,movesPage});
   var table=Theme.Table();source=Theme.Combo(db.pokemon.Select(p=>p.name),Value.Data.name);name=new PixelTextBox{Dock=DockStyle.Fill,Font=Theme.Input()};level=Theme.Number(100,1,999);hp=Theme.Number(100,0,999999);status=Theme.Combo(Mechanics.Statuses,Value.Status);status.Enabled=false;ability=new PixelTextBox{Dock=DockStyle.Fill,Font=Theme.Input()};item=new PixelTextBox{Dock=DockStyle.Fill,Font=Theme.Input()};Theme.Row(table,"시트에서 불러오기",source);Theme.Row(table,"이름",name);Theme.Row(table,"레벨",level);Theme.Row(table,"현재 HP",hp);for(int i=0;i<3;i++){type[i]=Theme.Combo(new[]{"없음"}.Concat(db.types),"없음");Theme.Row(table,"타입 "+(i+1),type[i]);}Theme.Row(table,"상태 (상태 창)",status);Theme.Row(table,"특성",ability);Theme.Row(table,"소지품",item);var heal=new FlatButton{Text="현재 설정 기준 HP 가득 회복",Dock=DockStyle.Fill};Theme.Row(table,"HP",heal);var info=Theme.Label("등록된 특성·도구만 적용. 배틀 규칙에서 확인하세요.",45);info.ForeColor=Theme.Muted;Theme.Row(table,"판정 범위",info);dataPage.Controls.Add(table);
   aa=new PixelTextBox{Multiline=true,AcceptsReturn=true,AcceptsTab=true,WordWrap=false,ScrollBars=ScrollBars.Both,Dock=DockStyle.Fill,Font=new Font(Fonts.AA,12),BorderStyle=BorderStyle.FixedSingle};aaPage.Padding=new Padding(15);aaPage.Controls.Add(aa);var hint=Theme.Label("공백·줄바꿈을 유지합니다. 배틀 창에서는 AA 전체가 보이도록 비율을 맞춥니다.",45);hint.ForeColor=Theme.Muted;aaPage.Controls.Add(hint);
   var grid=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=5,Padding=new Padding(18)};foreach(string h in new[]{"능력치","종족치","개체치","랭크","배율"}){grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,20));grid.Controls.Add(Theme.Label(h));}for(int i=0;i<6;i++){grid.RowStyles.Add(new RowStyle(SizeType.Absolute,48));grid.Controls.Add(Theme.Label(Engine.Names[i]),0,i+1);bases[i]=Theme.Number(100,1,999);ivs[i]=Theme.Number(0,0,31);stages[i]=Theme.Number(0,-6,6);mult[i]=Theme.Number(1,.1m,100,2);grid.Controls.Add(bases[i],1,i+1);grid.Controls.Add(ivs[i],2,i+1);grid.Controls.Add(stages[i],3,i+1);grid.Controls.Add(mult[i],4,i+1);if(i==0){stages[i].Enabled=false;mult[i].Enabled=false;}}statsPage.Controls.Add(grid);
   var mt=Theme.Table();for(int i=0;i<4;i++){moves[i]=new PixelComboBox{Dock=DockStyle.Fill,Font=Theme.Input()};moves[i].Items.AddRange(db.moves.Select(m=>m.name).Distinct().Cast<object>().ToArray());Theme.Row(mt,"기술 "+(i+1),moves[i]);}var explanation=new PixelLabel{Text="기술명을 입력해 검색할 수 있습니다.\r\n등록된 상태·날씨 효과는 자동 적용됩니다. 자세한 지원 범위는 배틀 규칙에서 확인하세요.",AutoSize=true,MaximumSize=new Size(530,0),ForeColor=Theme.Muted};Theme.Row(mt,"안내",explanation);movesPage.Controls.Add(mt);
   var foot=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=65,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(12)};var apply=new FlatButton{Text="적용",Primary=true,Size=new Size(100,38)};var cancel=new FlatButton{Text="취소",Size=new Size(85,38),DialogResult=DialogResult.Cancel};foot.Controls.AddRange(new Control[]{apply,cancel});Controls.Add(tabs);Controls.Add(foot);CancelButton=cancel;
   Fill();source.SelectedIndexChanged+=(s,e)=>{var p=db.pokemon.FirstOrDefault(x=>x.name==(string)source.SelectedItem);if(p!=null){string art=aa.Text;Value=new Fighter(p){AA=art};Fill();}};heal.Click+=(s,e)=>{try{ReadFields(false);hp.Value=Engine.Stats(Value,other,rules)[0];}catch(Exception ex){GameDialog.Show(this,ex.Message,"입력 확인",MessageBoxButtons.OK,MessageBoxIcon.Information);}};apply.Click+=(s,e)=>{try{ReadFields(true);Value.HP=Math.Min(Value.HP,Engine.Stats(Value,other,rules)[0]);DialogResult=DialogResult.OK;Close();}catch(Exception ex){GameDialog.Show(this,ex.Message,"입력 확인",MessageBoxButtons.OK,MessageBoxIcon.Information);}};
  }
  void Fill(){name.Text=Value.Data.name;level.Value=Value.Data.level;hp.Value=Value.HP;status.SelectedItem=Value.Status;ability.Text=Value.Data.ability;item.Text=Value.Data.item;aa.Text=Value.AA;for(int i=0;i<3;i++)type[i].SelectedItem=i<Value.Data.types.Length?Value.Data.types[i]:"없음";for(int i=0;i<6;i++){bases[i].Value=Value.Data.@base[i];ivs[i].Value=Value.Data.iv[i];stages[i].Value=Value.Stages[i];mult[i].Value=(decimal)Value.Multipliers[i];}for(int i=0;i<4;i++)moves[i].Text=i<Value.Moves.Length?Value.Moves[i]:"";}
  void ReadFields(bool validate){if(string.IsNullOrWhiteSpace(name.Text))throw new Exception("이름을 입력하세요.");var ts=type.Select(c=>(string)c.SelectedItem).Where(t=>t!="없음").Distinct().ToArray();if(ts.Length==0)throw new Exception("타입을 하나 이상 선택하세요.");string[] ms=moves.Select(c=>c.Text.Trim()).Where(t=>t.Length>0).Concat((Value.Moves??new string[0]).Skip(4)).ToArray();if(validate&&(ms.Length==0||ms.Any(n=>!db.moves.Any(m=>m.name==n))))throw new Exception("목록에 있는 기술을 하나 이상 선택하세요.");Value.Data.ability=ability.Text.Trim();AbilityRuntime.Reset(Value);Value.Data.item=item.Text.Trim();Value.Data.name=name.Text.Trim();Value.Data.level=(int)level.Value;Value.Data.types=ts;Value.HP=(int)hp.Value;Value.Status=(string)status.SelectedItem;Value.AA=aa.Text;Value.Data.@base=bases.Select(n=>(int)n.Value).ToArray();Value.Data.iv=ivs.Select(n=>(int)n.Value).ToArray();Value.Stages=stages.Select(n=>(int)n.Value).ToArray();Value.Multipliers=mult.Select(n=>(double)n.Value).ToArray();if(validate){Value.Moves=ms;Value.Selected=0;}}
 }
 // 목록에서 하나를 고르는 도트 창(임의의 능력·종족치 값 등)
 class ChoiceDialog:Form {
  public int Selected;
  public ChoiceDialog(string title,string message,string[] options){
   Load+=(s,e)=>Theme.Enlarge(this);Text=title;Size=new Size(560,520);StartPosition=FormStartPosition.CenterParent;Font=Theme.UI();BackColor=Color.White;
   var list=new PixelChoiceList{Dock=DockStyle.Fill};foreach(string option in options??new string[0])list.Items.Add(option);if(list.Items.Count>0)list.SelectedIndex=0;list.SelectedIndexChanged+=(s,e)=>Selected=Math.Max(0,list.SelectedIndex);
   var ok=new FlatButton{Text="결정",Dock=DockStyle.Bottom,Height=55,Primary=true,DialogResult=DialogResult.OK};
   Controls.Add(list);Controls.Add(new PixelLabel{Text=message,Dock=DockStyle.Top,Height=60});Controls.Add(ok);list.BringToFront();AcceptButton=ok;
  }
 }
